"""Mês atual, datas encerradas, configuração e rodízio no portal isolado."""
import unittest
import test_login_month_music_browser as login_module
import test_frontend_access as base
class ScheduleEditWindowBrowserTests(unittest.TestCase):
 setUpClass=classmethod(login_module.LoginMonthMusicTests.setUpClass.__func__);tearDownClass=classmethod(login_module.LoginMonthMusicTests.tearDownClass.__func__)
 go=login_module.LoginMonthMusicTests.go;choose=login_module.LoginMonthMusicTests.choose;login=login_module.LoginMonthMusicTests.login;department=login_module.LoginMonthMusicTests.department;sign_in=login_module.LoginMonthMusicTests.sign_in
 def setUp(self):
  login_module.LoginMonthMusicTests.setUp(self);self.page.clock.set_fixed_time('2026-11-04T15:00:00Z');self.page.reload();self.page.wait_for_selector('.church-portal-cards')
 tearDown=login_module.LoginMonthMusicTests.tearDown
 def sound(self):self.sign_in();self.department('Sonoplastia');self.page.wait_for_selector('[data-calendar-volunteer]')
 def confirm(self,names,department="sonoplastia"):
  return self.page.evaluate("""async({names,department})=>{for(const name of names){const c=await IASDPISchedules.request('iasdpi_registry_catalog'),d=c.departments.find(d=>d.code===department),p=c.people.find(p=>p.name===name),m=c.memberships.find(m=>m.person_id===p.id&&m.department_id===d.id),r=c.roles.find(r=>r.department_id===d.id&&r.general_assignment);await IASDPISchedules.request('iasdpi_registry_save',{p_person:p.id,p_expected_person_version:p.version,p_person_patch:{},p_links:[{department_id:d.id,expected_version:m.version,patch:{participation_confirmed:true,role_ids:[r.id],weekdays:Object.fromEntries(Array.from({length:7},(_,i)=>[i,'available']))}}],p_request_id:crypto.randomUUID()});}return true;}""",{'names':names,'department':department})
 def test_november_opens_with_selectors_today_and_future_only(self):
  self.sound();self.assertEqual(self.page.locator('#schedule-month').input_value(),'2026-11');self.assertEqual(self.page.locator('[data-calendar-volunteer]').count(),12)
  self.assertEqual(self.page.locator('.monthly-cell:has([data-day="2026-11-01"]) select').count(),0);self.assertIn('Encerrado',self.page.locator('.monthly-cell:has([data-day="2026-11-01"])').inner_text())
  self.assertTrue(self.page.locator('.monthly-cell:has([data-day="2026-11-04"]) select').is_enabled())
 def test_current_manual_save_reload_and_historical_twenty_preserved(self):
  self.sound();original=self.page.evaluate('JSON.stringify(IASDPIKnownPreviewSeed.rows)');field=self.page.locator('[data-calendar-volunteer]').first;person=field.locator('option:not([value=""]):not([disabled])').first.get_attribute('value');field.select_option(person)
  self.page.locator('[data-b1-action=save]').click();self.page.wait_for_function("()=>document.querySelector('#b1-feedback')?.textContent.includes('salvas nesta aba')");self.page.locator('[data-b1-action=reload]').click();self.page.wait_for_selector('[data-calendar-volunteer]');self.assertEqual(self.page.locator('[data-calendar-volunteer]').first.input_value(),person);self.assertEqual(original,self.page.evaluate('JSON.stringify(IASDPIKnownPreviewSeed.rows)'))
 def test_unknown_availability_reports_reason_without_inventing_assignments(self):
  self.sound();self.page.locator('[data-b1-action=prefill]').click();self.page.wait_for_function("()=>document.querySelector('#b1-feedback')?.textContent.includes('Nenhuma pessoa elegível')");self.assertEqual(self.page.locator('.schedule-rotation-reasons a').inner_text(),'Conferir equipe');self.assertTrue(all(not value for value in self.page.locator('[data-calendar-volunteer]').evaluate_all('es=>es.map(e=>e.value)')))
 def test_prefill_after_confirmation_balances_and_preserves_manual_choice(self):
  self.sound();self.confirm(['Luan Vaz','Samuel Ferreira']);field=self.page.locator('[data-calendar-volunteer]').first;chosen=field.locator('option').filter(has_text='Luan Vaz').get_attribute('value');field.select_option(chosen)
  self.page.locator('[data-b1-action=prefill]').click();self.page.wait_for_function("()=>document.querySelector('#b1-feedback')?.textContent.includes('vagas sugeridas')")
  values=self.page.locator('[data-calendar-volunteer]').evaluate_all('es=>es.map(e=>e.value)');self.assertTrue(all(values));self.assertEqual(values[0],chosen);self.assertEqual(len(set(values)),2);counts=[values.count(v) for v in set(values)];self.assertLessEqual(max(counts)-min(counts),1)
 def test_admin_can_change_future_window_without_locking_current_or_deleting(self):
  self.sound();events=self.page.evaluate('IASDPIB1Preview.events.length');self.page.locator('[data-b1-nav=schedule-settings]').first.click();self.page.wait_for_selector('#daily-settings');self.page.select_option('#daily-settings [name=planning_months]','1');self.page.locator('#daily-settings button[type=submit]').click();self.page.wait_for_function("async()=>(await IASDPISchedules.request('iasdpi_schedule_settings_get')).planning_months===1")
  self.go('schedule-build');self.page.wait_for_selector('.monthly-calendar');self.department('Sonoplastia');self.page.wait_for_selector('[data-calendar-volunteer]');self.assertEqual(self.page.locator('#schedule-month').input_value(),'2026-11')
  self.page.locator('[data-b1-action=month][data-direction="1"]').click();self.page.wait_for_function("()=>document.querySelector('#schedule-month')?.value==='2026-12'");self.page.wait_for_selector('[data-calendar-volunteer]')
  self.page.locator('[data-b1-action=month][data-direction="1"]').click();self.page.wait_for_function("()=>document.querySelector('#schedule-month')?.value==='2027-01'");self.assertEqual(self.page.locator('[data-calendar-volunteer]').count(),0);self.assertGreaterEqual(self.page.evaluate('IASDPIB1Preview.events.length'),events)
 def test_leader_cannot_change_administrative_window(self):
  self.login('som.iasdpi');result=self.page.evaluate("async()=>{const s=await IASDPISchedules.request('iasdpi_schedule_settings_get');try{await IASDPISchedules.request('iasdpi_schedule_settings_save',{p_expected_version:s.version,p_data:{planning_months:6}});return 'FAIL';}catch(e){return e.message;}}")
  self.assertIn('Somente administrador',result);self.assertEqual(self.page.locator('[data-b1-nav=schedule-settings]').count(),0)
 def test_forged_past_event_and_future_month_are_rejected_by_demo_rpc(self):
  self.sound();result=self.page.evaluate("""async()=>{const c=await IASDPISchedules.request('iasdpi_schedule_catalog'),d=c.departments.find(d=>d.code==='sonoplastia');let denied=0;for(const date of ['2026-11-03','2027-11-07'])try{await IASDPISchedules.request('iasdpi_schedule_event_create',{p_id:crypto.randomUUID(),p_data:{department_id:d.id,title:'Tentativa sintética',date},p_request_id:crypto.randomUUID()});}catch{denied++;}return denied;}""");self.assertEqual(result,2)
 def test_mobile_and_december_boundary_use_sao_paulo(self):
  self.sound();out=base.ROOT/'dist/schedule-edit-window'
  for width,label in [(1440,'desktop'),(390,'mobile')]:
   self.page.set_viewport_size({'width':width,'height':1000});self.assertLessEqual(self.page.evaluate('document.documentElement.scrollWidth'),width);self.page.screenshot(path=str(out/('novembro-'+label+'.png')),full_page=True)
  self.page.clock.set_fixed_time('2026-12-01T01:00:00Z');self.page.reload();self.page.wait_for_selector('.monthly-calendar');self.department('Sonoplastia');self.assertEqual(self.page.locator('#schedule-month').input_value(),'2026-11')
 def test_prefill_consults_communication_commitment_without_blocking(self):
  self.sound();self.confirm(['Gabriel Macedo'],'comunicacao');self.confirm(['Gabriel Macedo','Samuel Ferreira'])
  booked=self.page.evaluate("""async()=>{const c=await IASDPISchedules.request('iasdpi_registry_catalog'),d=c.departments.find(d=>d.code==='comunicacao'),role=c.roles.find(r=>r.department_id===d.id&&r.general_assignment),p=c.people.find(p=>p.name==='Gabriel Macedo'),e=await IASDPISchedules.request('iasdpi_schedule_event_create',{p_id:crypto.randomUUID(),p_data:{department_id:d.id,date:'2026-11-07',title:'Compromisso fictício para conflito'},p_request_id:crypto.randomUUID()});await IASDPISchedules.request('iasdpi_schedule_plan_save',{p_id:crypto.randomUUID(),p_expected_version:0,p_data:{department_id:d.id,month:'2026-11-01',title:'Comunicação fictícia',status:'published',requirements:[{id:crypto.randomUUID(),event_id:e.id,role_id:role.id,required_count:1,notes:'',assignments:[{id:crypto.randomUUID(),person_id:p.id,timing_mode:'day'}]}]},p_request_id:crypto.randomUUID()});return p.id;}""")
  self.page.locator('[data-b1-action=prefill]').click();self.page.wait_for_function("()=>document.querySelector('#b1-feedback')?.textContent.includes('vagas sugeridas')")
  field=self.page.locator('.monthly-cell:has([data-day="2026-11-07"]) [data-calendar-volunteer]');self.assertTrue(field.input_value());self.assertTrue(field.locator('option[value="'+booked+'"]').is_enabled());self.assertFalse(self.page.evaluate("async id=>{const c=await IASDPISchedules.request('iasdpi_schedule_catalog'),d=c.departments.find(d=>d.code==='sonoplastia'),context=await IASDPISchedules.request('iasdpi_schedule_rotation_context',{p_department:d.id,p_month:'2026-11-01'});return context.people.find(p=>p.person_id===id).days.find(day=>day.date==='2026-11-07').conflict;}",booked))
 def test_clear_and_save_keep_past_assignments_unchanged(self):
  self.sound();past=self.page.evaluate("""async()=>{const c=await IASDPIG6Preview.raw('iasdpi_schedule_catalog'),d=c.departments.find(d=>d.code==='sonoplastia'),r=c.roles.find(r=>r.department_id===d.id&&r.general_assignment),p=c.people.find(p=>p.name==='Luan Vaz'),e=await IASDPIG6Preview.raw('iasdpi_schedule_event_create',{p_id:crypto.randomUUID(),p_data:{department_id:d.id,date:'2026-11-01',title:'Registro histórico sintético'},p_request_id:crypto.randomUUID()}),id=crypto.randomUUID();await IASDPIG6Preview.raw('iasdpi_schedule_plan_save',{p_id:id,p_expected_version:0,p_data:{department_id:d.id,month:'2026-11-01',title:'Plano com passado preservado',status:'draft',requirements:[{id:crypto.randomUUID(),event_id:e.id,role_id:r.id,required_count:1,notes:'Preservar',assignments:[{id:crypto.randomUUID(),person_id:p.id,timing_mode:'day'}]}]},p_request_id:crypto.randomUUID()});return {plan:id,person:p.id,event:e.id};}""")
  self.page.locator('[data-b1-action=reload]').click();self.page.wait_for_function("()=>document.querySelector('.monthly-cell:has([data-day=\"2026-11-01\"])')?.textContent.includes('Luan Vaz')")
  self.assertEqual(self.page.locator('.monthly-cell:has([data-day="2026-11-01"]) select').count(),0)
  field=self.page.locator('[data-calendar-volunteer]').first;field.select_option(field.locator('option:not([value=""]):not([disabled])').first.get_attribute('value'));self.page.once('dialog',lambda d:d.accept());self.page.locator('[data-b1-action=clear]').click();self.page.locator('[data-b1-action=save]').click();self.page.wait_for_function("()=>document.querySelector('#b1-feedback')?.textContent.includes('salvas nesta aba')")
  saved=self.page.evaluate('(x)=>[...IASDPIB1Preview.plans.values()].find(p=>p.id===x.plan).requirements.find(r=>r.event_id===x.event)',past);self.assertEqual(saved['assignments'][0]['person_id'],past['person']);self.assertEqual(saved['notes'],'Preservar')
 def test_annual_elder_calendar_only_enables_active_and_released_months(self):
  self.sign_in();self.page.locator('.monthly-departments button').get_by_text('Ancionato',exact=True).click();self.page.wait_for_selector('[data-kind=monthly]');self.page.locator('[data-kind=monthly]').click();self.page.wait_for_selector('.elder-year-calendar')
  self.assertEqual(self.page.locator('.elder-month-card').count(),12);self.assertTrue(self.page.locator('[data-elder-period="monthly:2026-10-01"] select').is_disabled());self.assertTrue(self.page.locator('[data-elder-period="monthly:2026-11-01"] select').is_enabled());self.assertTrue(self.page.locator('[data-elder-period="monthly:2026-12-01"] select').is_enabled())
 def test_publisher_without_edit_permission_can_only_publish_existing_draft(self):
  self.sound();plan=self.page.evaluate("""async()=>{const c=await IASDPISchedules.request('iasdpi_schedule_catalog'),d=c.departments.find(d=>d.code==='sonoplastia'),role=c.roles.find(r=>r.department_id===d.id&&r.general_assignment),person=c.people.find(p=>p.name==='Luan Vaz'),event=IASDPIB1Preview.events.find(e=>e.scheduled_on==='2026-11-04'),id=crypto.randomUUID();const saved=await IASDPISchedules.request('iasdpi_schedule_plan_save',{p_id:id,p_expected_version:0,p_data:{department_id:d.id,month:'2026-11-01',title:'Rascunho fictício autorizado',status:'draft',requirements:[{id:crypto.randomUUID(),event_id:event.id,role_id:role.id,required_count:1,notes:'',assignments:[{id:crypto.randomUUID(),person_id:person.id,timing_mode:'day'}]}]},p_request_id:crypto.randomUUID()});IASDPIG6Preview.accounts.find(a=>a.alias==='editor.iasdpi').caps[d.id]={view:true,edit:false,publish:true};return saved;}""")
  self.page.locator('#auth-logout').click();self.page.wait_for_function('()=>!IASDPIAuth.identityKey()');self.login('editor.iasdpi')
  result=self.page.evaluate("async p=>IASDPISchedules.request('iasdpi_schedule_plan_save',{p_id:p.id,p_expected_version:p.version,p_data:{status:'published'},p_request_id:crypto.randomUUID()})",plan);self.assertEqual(result['status'],'published')
  denied=self.page.evaluate("async p=>{try{await IASDPISchedules.request('iasdpi_schedule_plan_save',{p_id:p.id,p_expected_version:p.version,p_data:{title:'Edição proibida'},p_request_id:crypto.randomUUID()});return false;}catch{return true;}}",result);self.assertTrue(denied)
